import type { BeliefState, Parcel, Position } from "../domain.js";
import type { AgentCapability } from "./contracts.js";

/**
 * Energy-aware task selection.
 * The initial policy uses reward divided by Manhattan distance.
 * The evolved policy incorporates energy constraints and door/key dependencies.
 */
export const taskSelectionModule: AgentCapability = {
  id: "task-selection",
  version: 2,
  purpose: "Rank visible work items using an energy-aware and door-aware heuristic.",
};

export function selectParcel(state: BeliefState, from: Position): Parcel | undefined {
  const parcels = [...state.parcels.values()].filter((parcel) => !parcel.carriedBy);
  if (parcels.length === 0) return undefined;

  // If energy is known and low, prefer closer tasks to avoid exhaustion.
  const energy = state.energy;
  const doors = state.doors ?? [];
  const keys = state.keys ?? [];

  // Calculate the cost of a task considering doors and keys.
  const taskCost = (parcel: Parcel): number => {
    const distance = Math.abs(parcel.x - from.x) + Math.abs(parcel.y - from.y);
    // Estimate the cost of the round trip (pickup + delivery).
    // We assume the delivery target is at a fixed distance or we can estimate it.
    // For now, we use a heuristic that penalizes tasks that are far away if energy is low.
    let cost = distance * 2; // Round trip estimate

    // If there are doors, check if a key is needed.
    // This is a simplified check: if any door is in the path, we assume a key is needed.
    // A more robust check would require pathfinding, but we use a heuristic here.
    if (doors.length > 0 && keys.length === 0) {
      // Penalize tasks that are likely behind a door.
      cost += 10;
    }

    return cost;
  };

  const utility = (parcel: Parcel): number => {
    const cost = taskCost(parcel);
    if (energy !== undefined && energy < cost) {
      // If the agent cannot afford the task, heavily penalize it.
      return -1;
    }
    return parcel.reward / (1 + cost);
  };

  return parcels.sort((a, b) => utility(b) - utility(a))[0];
}

